      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Only fair, specific disclosure in the Disclosure Letter counts, with enough detail for the Buyer to identify the nature and scope of the matter."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete; pro-sandbagging clause"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A Condition Precedent requiring Bluefen's unconditional written consent, in a form satisfactory to the Buyer acting reasonably."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repay the facility at Completion out of the purchase price under a payout letter from Riverlark."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Treat the bonuses and all on-costs as Transaction Expenses / Indebtedness and deduct them from the price in the funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A broadened specific indemnity covering all Loss arising from any failure of the Company to own or have unrestricted use of the SOW3 materials."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Full file before signing, Notifiable Data Breaches compliance, specific indemnity, escrow"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "If they are not ordinary course, require the Seller to terminate them or bear the cost."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Limitations apply only to general Warranty Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Run our own ASIC company extract and PPSR searches against the Seller and the Company."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "The IP warranties to remain outside the \"settled\" general regime."
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "The AUD 25k de minimis (about 0.1% of price) is within market range.",
  "names_manipulation": true
}

